/* Standalone comparison variant. The normal homepage keeps its current menu. */
let sidebarCatalogSelection={kind:'series',id:'pobeda'};
const sidebarIconPaths={sale:'<circle cx="7" cy="7" r="2.5"/><circle cx="17" cy="17" r="2.5"/><path d="M5 20 20 5"/>',pobeda:'<path d="M3 5h18M6 5v5m6-5v5m6-5v5M4 10h4l1 6H3l1-6Zm6 0h4l1 6H9l1-6Zm6 0h4l1 6h-6l1-6Z"/>',liniya:'<path d="M3 8h18v7H3zM6 18h12M7 5h10"/>',olimpika:'<path d="M3 6h18M7 6l-2 9h14l-2-9M8 18h8"/><path d="M9 10h6"/>','olimpika-2':'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/>',diffuse:'<path d="M4 6h16l-2 11H6L4 6ZM8 20h8"/>',surface:'<path d="M5 5h14v12H5zM8 20h8"/>',impuls:'<path d="m12 3 8 9-8 9-8-9 8-9ZM8 12h8"/>',legenda:'<path d="M4 5h16M7 5v15m10-15v15M7 12h10M4 20h6m4 0h6"/>',outdoor:'<path d="M12 3v18M6 7h12l-2-4H8L6 7ZM8 11h8M8 21h8"/>',wall:'<path d="M5 4v16M5 12h8m0-5 6 5-6 5V7Z"/>',strip:'<path d="M4 8h16v8H4zM7 11v2m5-2v2m5-2v2"/>',profile:'<path d="M4 5v13h16V5M8 5v9h8V5"/>'};
function sidebarIcon(key){return `<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${sidebarIconPaths[key]||sidebarIconPaths.surface}</svg>`}
function sidebarItem(kind,id,label,icon){const selected=sidebarCatalogSelection.kind===kind&&String(sidebarCatalogSelection.id)===String(id);return `<button class="sidebar-catalog-item${selected?' active':''}${kind==='sale'?' sidebar-catalog-sale':''}" data-sidebar-kind="${kind}" data-sidebar-id="${id}" aria-pressed="${selected}">${sidebarIcon(icon)}<span>${E(label)}</span><span class="sidebar-item-arrow" aria-hidden="true">›</span></button>`}
function sidebarNavigation(kind){if(kind==='series')return `<h2 class="sidebar-nav-heading">Системы и линейки</h2>${catalogMenuFamilies.map(f=>sidebarItem('series',f.key,f.label,f.key)).join('')}`;return `<h2 class="sidebar-nav-heading">Товарные категории</h2>${categoryNames.map((name,n)=>sidebarItem('category',n,name,({0:'pobeda',1:'pobeda',2:'liniya',3:'olimpika',4:'outdoor',5:'surface',6:'impuls',7:'wall',8:'legenda',9:'strip',10:'profile'})[n])).join('')}<div class="sidebar-sale-block">${sidebarItem('sale','all','Распродажа','sale')}</div>`}
function sidebarMenuRow(label,attributes){return `<button ${attributes}>${E(label)}</button>`}
function sidebarGroup(title,links,note=''){return `<section class="sidebar-product-group"><h3>${E(title)}</h3>${note?`<p>${E(note)}</p>`:''}<div>${links}</div></section>`}
function sidebarSeriesContent(f){let groups='';
 if(f.key==='pobeda'){groups+=sidebarGroup('Светильники',sidebarMenuRow('Светильники Победа','data-catalog-lights'),'Общие для Pro и Eco');['shinoprovody','pitaniya','komplektuyshchie'].forEach(type=>{const title=({shinoprovody:'Шинопроводы',pitaniya:'Питание',komplektuyshchie:'Комплектующие'})[type];const links=catalogPobedaBranches().map(branch=>{const node=branch.children.find(c=>c.url.includes(type));return node?sidebarMenuRow(title+' '+catalogPobedaVariant(branch),`data-native="${E(node.url)}"`):''}).join('');groups+=sidebarGroup(title,links)})}
 else if(f.key==='olimpika'){groups=sidebarGroup('Светильники',catalogChildren(f).map(c=>sidebarMenuRow(c.title.replace('Встраиваемые светильники «Олимпика»','Светильники'),`data-native="${E(c.url)}"`)).join(''))+sidebarGroup('Материалы',sidebarMenuRow('Каталоги и инструкции','data-docs'))}
 else{groups=sidebarGroup('Продукция',sidebarMenuRow('Смотреть продукцию',f.category!==null?`data-category="${f.category}"`:`data-series="${f.key}"`))}
 const all=f.category!==null?`data-category="${f.category}"`:`data-series="${f.key}"`;return `<div class="sidebar-catalog-content-heading"><div><h2 id="sidebar-content-title">${E(f.label)}</h2><p>${E(f.description)}</p></div><button ${all}>Смотреть все <span aria-hidden="true">↗</span></button></div><div class="sidebar-product-columns">${groups}</div><div class="sidebar-catalog-landing">${catalogSeriesLink(f)}</div>`
}
function sidebarCategoryContent(n){const related=catalogMenuFamilies.filter(f=>f.category===n);if(n===0)return sidebarSeriesContent(catalogMenuFamilies.find(f=>f.key==='pobeda')).replace('<h2 id="sidebar-content-title">Победа</h2>',`<h2 id="sidebar-content-title">${E(categoryNames[n])}</h2>`);return `<div class="sidebar-catalog-content-heading"><div><h2 id="sidebar-content-title">${E(categoryNames[n])}</h2><p>Светильники и компоненты ChampionLED</p></div><button data-category="${n}">Смотреть все <span aria-hidden="true">↗</span></button></div><div class="sidebar-product-columns">${sidebarGroup('Продукция',sidebarMenuRow('Смотреть продукцию',`data-category="${n}"`))}${related.length?sidebarGroup('Системы и линейки',related.map(f=>sidebarMenuRow(f.label,`data-sidebar-kind="series" data-sidebar-id="${f.key}"`)).join('')):''}</div>`}
function renderSidebarCatalog(kind=sidebarCatalogSelection.kind,id=sidebarCatalogSelection.id,updateUrl=true){sidebarCatalogSelection={kind,id};const panel=$('#sidebar-catalog-content');if(!panel)return;$$('.sidebar-catalog-navigation [data-sidebar-kind]').forEach(b=>{const active=b.dataset.sidebarKind===kind&&b.dataset.sidebarId===String(id);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});if(kind==='series'){const f=catalogMenuFamilies.find(f=>f.key===id)||catalogMenuFamilies[0];catalogSelectedFamily=f.key;panel.innerHTML=sidebarSeriesContent(f)}else if(kind==='category'){panel.innerHTML=sidebarCategoryContent(Number(id))}else{panel.innerHTML=`<div class="sidebar-catalog-content-heading"><div><h2 id="sidebar-content-title">Распродажа</h2><p>Интерьерные светильники премиального сегмента по сниженным ценам.</p></div><button data-sale>Смотреть все <span aria-hidden="true">↗</span></button></div><div class="sidebar-product-columns">${sidebarGroup('Светильники',['Накладные','Встраиваемые','Подвесные'].map(label=>sidebarMenuRow(label,'data-sale')).join(''))}</div><div class="focus-sale-products sidebar-sale-products">${SALE_PRODUCTS.map(p=>`<button data-product="${p.id}"><img src="${p.images[0]}" alt="${E(p.name)}"><span>${E(p.name)}</span><strong>${rub(p.price)}</strong></button>`).join('')}</div>`}panel.scrollTop=0;if(updateUrl)history.replaceState(null,'','#sidebar-'+(kind==='series'?id:kind==='category'?'category-'+id:'sale'));resizeSidebarCatalog()}
function resizeSidebarCatalog(){const panel=$('.sidebar-catalog-panel');if(!panel||$('#menu').hidden)return;const rect=panel.getBoundingClientRect(),scale=rect.width/panel.offsetWidth||1;panel.style.height=Math.max(240,Math.min(660,(window.innerHeight-rect.top-10)/scale))+'px';sizeUnifiedCatalog()}
const sidebarPreviousMenu=menu;
$('#catalog-toggle').removeEventListener('click',sidebarPreviousMenu);
menu=function(){const m=$('#menu');if(!m.hidden){closeCatalog();return}m.innerHTML=`<div class="menu-inner catalog-panel unified-catalog-panel sidebar-catalog-panel"><div class="sidebar-catalog-columns"><nav class="sidebar-catalog-navigation sidebar-navigation--systems" aria-label="Системы и линейки">${sidebarNavigation('series')}</nav><nav class="sidebar-catalog-navigation sidebar-navigation--categories" aria-label="Товарные категории">${sidebarNavigation('categories')}</nav><section id="sidebar-catalog-content" class="sidebar-catalog-content" aria-labelledby="sidebar-content-title" aria-live="polite"></section></div></div>`;let shade=$('#catalog-shade');if(!shade){shade=document.createElement('button');shade.id='catalog-shade';shade.type='button';shade.dataset.closeMenu='';shade.setAttribute('aria-label','Закрыть каталог');shade.tabIndex=-1;document.body.appendChild(shade)}shade.hidden=false;document.body.classList.add('catalog-visible');m.hidden=false;$('#catalog-toggle').setAttribute('aria-expanded','true');renderSidebarCatalog(sidebarCatalogSelection.kind,sidebarCatalogSelection.id,false);window.scrollTo({top:0,behavior:'auto'});requestAnimationFrame(resizeSidebarCatalog)};
$('#catalog-toggle').addEventListener('click',menu);
document.addEventListener('click',e=>{const b=e.target.closest('[data-sidebar-kind]');if(b)renderSidebarCatalog(b.dataset.sidebarKind,b.dataset.sidebarId)});
window.addEventListener('resize',resizeSidebarCatalog);
const sidebarPreviousHashTarget=showHashTarget;
window.removeEventListener('hashchange',sidebarPreviousHashTarget);
showHashTarget=function(){if(location.hash.startsWith('#sidebar-')||location.hash.startsWith('#catalog')){const key=location.hash.replace(/^#(?:sidebar|catalog)-?/,'');if(key.startsWith('category-'))sidebarCatalogSelection={kind:'category',id:Number(key.slice(9))||0};else if(key==='sale')sidebarCatalogSelection={kind:'sale',id:'all'};else if(catalogMenuFamilies.some(f=>f.key===key))sidebarCatalogSelection={kind:'series',id:key};if($('#menu').hidden)menu();else renderSidebarCatalog(sidebarCatalogSelection.kind,sidebarCatalogSelection.id,false);return}sidebarPreviousHashTarget()};
window.addEventListener('hashchange',showHashTarget);
if(!$('#menu').hidden)closeCatalog();
document.fonts.ready.then(showHashTarget);
